def choose_move(observation):
    # Defensive extraction of relevant information
    grid = observation.get('grid', [])
    position = observation.get('position', (0, 0))
    size = observation.get('size', (0, 0))
    target_positions = observation.get('targets', [])
    enemies = observation.get('enemies', [])
    resources = observation.get('resources', [])
    territory = observation.get('territory', [])

    x, y = position

    # Determine possible moves: stay in place or move in four directions
    moves = {
        'stay': (0, 0),
        'up': (0, -1),
        'down': (0, 1),
        'left': (-1, 0),
        'right': (1, 0)
    }

    # Function to check if position is within grid bounds
    def in_bounds(nx, ny):
        return 0 <= nx < size[0] and 0 <= ny < size[1]

    # Function to check if the position is safe (not an enemy)
    def is_safe(nx, ny):
        for enemy in enemies:
            ex, ey = enemy.get('position', (None, None))
            if ex == nx and ey == ny:
                return False
        return True

    # Prioritize moves that lead to resources
    for move_name, (dx, dy) in moves.items():
        nx, ny = x + dx, y + dy
        if in_bounds(nx, ny) and is_safe(nx, ny):
            # Check for resource in the new position
            if any(r.get('position') == (nx, ny) for r in resources):
                return [dx, dy]

    # Pursuit or evasion: move towards targets if prioritized
    if target_positions:
        # Find the closest target
        def distance(a, b):
            return abs(a[0] - b[0]) + abs(a[1] - b[1])
        closest = min(target_positions, key=lambda t: distance(position, t))
        dx = dy = 0
        if closest[0] > x:
            dx = 1
        elif closest[0] < x:
            dx = -1
        if closest[1] > y:
            dy = 1
        elif closest[1] < y:
            dy = -1
        # Check if move is valid
        nx, ny = x + dx, y + dy
        if in_bounds(nx, ny) and is_safe(nx, ny):
            return [dx, dy]

    # If territory control info is available, move towards own territory
    if territory:
        # Assuming territory grid is same size as grid
        # Find each cell in our territory
        own_cells = [i for i, row in enumerate(territory)
                     for j, cell in enumerate(row) if cell]
        if own_cells:
            target_cell = min(own_cells, key=lambda c: abs(c[0] - y) + abs(c[1] - x))
            dx = 0
            dy = 0
            if target_cell[1] > x:
                dx = 1
            elif target_cell[1] < x:
                dx = -1
            if target_cell[0] > y:
                dy = 1
            elif target_cell[0] < y:
                dy = -1
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny) and is_safe(nx, ny):
                return [dx, dy]

    # As fallback, try to stay safe or move randomly among safe options
    for move_name, (dx, dy) in moves.items():
        nx, ny = x + dx, y + dy
        if in_bounds(nx, ny) and is_safe(nx, ny):
            return [dx, dy]

    # Default: stay in place if no safe move
    return [0, 0]
